import{_ as i,o as h,c as a,a2 as s}from"./chunks/framework.62rcL0wY.js";const t="/clickermann-guide-vi/so-do/bo-dem-anh.svg",d=JSON.parse('{"title":"Bộ đệm ảnh","description":"","frontmatter":{},"headers":[],"relativePath":"khai-niem/bo-dem-anh.md","filePath":"khai-niem/bo-dem-anh.md"}'),e={name:"khai-niem/bo-dem-anh.md"};function c(l,n,p,r,g,k){return h(),a("div",null,[...n[0]||(n[0]=[s('<h1 id="bo-dem-anh" tabindex="-1">Bộ đệm ảnh <a class="header-anchor" href="#bo-dem-anh" aria-label="Permalink to &quot;Bộ đệm ảnh&quot;">​</a></h1><p>Trang này giải thích cơ chế <strong>bộ đệm ảnh</strong> trong Clickermann, lý do bắt buộc phải gọi lệnh <code>GETSCREEN</code> trước khi đọc màu hay tìm ảnh và cách chỉ cập nhật một vùng màn hình để tăng tốc độ.</p><h2 id="tai-sao-phai-goi-getscreen" tabindex="-1">Tại sao phải gọi <code>GETSCREEN</code>? <a class="header-anchor" href="#tai-sao-phai-goi-getscreen" aria-label="Permalink to &quot;Tại sao phải gọi `GETSCREEN`?&quot;">​</a></h2><p>Các hàm và thủ tục đồ họa trong Clickermann (như <a href="/clickermann-guide-vi/lenh/man-hinh.html#pxl"><code>PXL</code></a>, <a href="/clickermann-guide-vi/lenh/man-hinh.html#pxlcount"><code>PXLCOUNT</code></a>, <a href="/clickermann-guide-vi/lenh/man-hinh.html#if-pixel-in-end-if"><code>IF_PIXEL_IN</code></a>, <a href="/clickermann-guide-vi/lenh/man-hinh.html#if-picture-in-end-if"><code>IF_PICTURE_IN</code></a>, <a href="/clickermann-guide-vi/lenh/man-hinh.html#scanpxl"><code>SCANPXL</code></a>, <a href="/clickermann-guide-vi/lenh/man-hinh.html#screenshot"><code>SCREENSHOT</code></a>...) <strong>không đọc trực tiếp từ màn hình đang hiển thị</strong> mà đọc từ một bức ảnh chụp lưu trong bộ nhớ gọi là <strong>bộ đệm ảnh</strong>.</p><p>Cách thiết kế này có hai tác dụng chính:</p><ol><li><strong>Tăng tốc độ xử lý:</strong> Thay vì làm việc trực tiếp với màn hình đang hiển thị, các lệnh đồ họa đọc dữ liệu từ ảnh chụp trong bộ đệm ảnh giúp chương trình chạy nhanh hơn.</li><li><strong>Tạo &quot;trí nhớ thị giác&quot; cho chương trình:</strong> Tại một thời điểm, trong bộ nhớ chỉ lưu duy nhất một bức ảnh chụp màn hình để các lệnh đồ họa trong script lấy dữ liệu từ đó.</li></ol><p><img src="'+t+`" alt="Màn hình thật, lệnh GETSCREEN và Bộ đệm ảnh"></p><p>Vì bộ đệm ảnh không tự động cập nhật khi màn hình bên ngoài thay đổi, mỗi khi bạn cần cập nhật trạng thái màn hình lưu trong bộ nhớ, bạn <strong>bắt buộc phải gọi lại <a href="/clickermann-guide-vi/lenh/man-hinh.html#getscreen"><code>GETSCREEN</code></a></strong>. Quên gọi <code>GETSCREEN</code> là lỗi rất thường gặp ở người mới học (trong trình soạn thảo thấy có màu nhưng khi chạy script lại không hoạt động).</p><h2 id="cap-nhat-rieng-mot-vung-de-tang-toc" tabindex="-1">Cập nhật riêng một vùng để tăng tốc <a class="header-anchor" href="#cap-nhat-rieng-mot-vung-de-tang-toc" aria-label="Permalink to &quot;Cập nhật riêng một vùng để tăng tốc&quot;">​</a></h2><p>Nếu bạn gọi <code>GETSCREEN</code> không có tham số, chương trình sẽ chụp toàn bộ màn hình (Suy luận: khi đang bật <a href="/clickermann-guide-vi/khai-niem/khoa-cua-so.html">chế độ khóa cửa sổ</a>, ảnh chụp tương ứng với phần tử đang khóa).</p><p>Khi script chỉ cần theo dõi một khu vực nhỏ (ví dụ một biểu tượng hoặc ô trạng thái từ tọa độ <code>10, 20</code> đến <code>100, 40</code>), bạn có thể truyền 4 tọa độ vùng vào <code>GETSCREEN(x1, y1, x2, y2)</code>:</p><div class="language-cms vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cms</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Chỉ cập nhật vùng hình chữ nhật (10, 20) -&gt; (100, 40) trong bộ đệm ảnh</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">GETSCREEN</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">10</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">20</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">100</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">40</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Kiểm tra màu đỏ (255) ngay trong vùng vừa cập nhật</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">IF_PIXEL_IN</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">10</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">20</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">100</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">40</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">255</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">   LCLICK</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">$_return1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">$_return2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">END_IF</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">HALT</span></span></code></pre></div><p>Khi truyền tọa độ vùng, chỉ đúng khu vực đó trong bộ đệm ảnh được chụp mới; trên một số hệ thống, cách này giúp lệnh <code>GETSCREEN</code> chạy nhanh hơn.</p><hr><p><em>Nguồn: Tài liệu trợ giúp <code>help.chm</code> (mục Màn hình, bài Khóa cửa sổ và phần FAQ).</em></p>`,15)])])}const m=i(e,[["render",c]]);export{d as __pageData,m as default};
